// Источник: web-тест .qa/e2e/tests/prayer-mode/pm-01-toggle-default-and-marking.spec.ts, план .qa/e2e/specs/prayer-mode.md, кейс .qa/tests/prayer-mode/PM-01-default-and-toggle.md
// Тикет #6a86f7e7 (6a86f7e7489027bf85afa2d9). Опора: F-103 «מצב תפילה ביחיד או במניין» · S-17.
// «По умолчанию יחיד»: web очищал localStorage; в приложении хранилище не очищается — опора на то, что все тесты режима
// возвращают «יחיד» в конце. Цвет фона (rgb 219,171,100) и шрифт Bold/Regular (getComputedStyle) не переносятся;
// «отмечен не только цветом» проверяется состоянием checked у radio.
import { expect, $, driver } from '@wdio/globals';
import { byText, byTextMatches, byLabelStartsWith, tapText, expectVisibleText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const TOTAL = 57;

/** Radio режима: Android — checkable-элемент с подписью/текстом, iOS — элемент с подписью. */
function radio(name: string) {
  return driver.isAndroid
    ? $(`//*[@checkable="true" and (@content-desc="${name}" or .//*[@text="${name}"])]`)
    : $(`-ios predicate string:label == "${name}" OR name == "${name}"`);
}
async function isChecked(name: string) {
  const el = await radio(name);
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true';
  const v = await el.getAttribute('value');
  return v === '1' || v === 'checked' || (await el.isSelected());
}
async function expectSelected(selected: string, other: string) {
  await driver.waitUntil(async () => (await isChecked(selected)) && !(await isChecked(other)),
    { timeoutMsg: `Ожидался выбранный «${selected}»` });
}

async function switchNusach(to: 'ספרדי' | 'אשכנזי') {
  await (await byLabelStartsWith('בחירת נוסח')).click();
  await tapText(to);
  const replace = await byText('החלף');
  if (await replace.isDisplayed().catch(() => false)) await replace.click();
  await expectVisibleText(`שחרית (${to})`);
}

describe('Режим молитвы «יחיד / מניין»', () => {
  afterEach(async () => { await toHome(); });

  it('PM-01 Переключатель «יחיד/מניין» вверху под счётчиком, по умолчанию «יחיד», выбранный отмечен #6a86f7e7 @prod-safe', async () => {
    // 1. שחרית (ספרדי): deep link или «תפילות» → «שחרית» → меню нусаха → «ספרדי».
    if (hasDeepLinks()) await openRoute('/prayer/shacharit_sfarad');
    else { await openPrayer('shacharit_ashkenaz', 'שחרית'); await switchNusach('ספרדי'); }
    await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();

    // 2. «קודם» до «1 מתוך 57».
    await goToPage(1, TOTAL);
    expect(await pageCounter()).toBe(`1 מתוך ${TOTAL}`);

    // 3. Radio «יחיד» и «מניין» — под счётчиком; по умолчанию «יחיד».
    const counter = await byTextMatches('\\d+ מתוך \\d+');
    const cy = (await counter.getLocation()).y + (await counter.getSize()).height;
    for (const name of ['יחיד', 'מניין']) {
      const el = await radio(name);
      await expect(el).toBeDisplayed();
      expect((await el.getLocation()).y).toBeGreaterThanOrEqual(cy);
    }
    await expectSelected('יחיד', 'מניין');

    // 4. «מניין» → выбран «מניין».
    await (await radio('מניין')).click();
    await expectSelected('מניין', 'יחיד');

    // 5. «יחיד» → выбран «יחיד» (состояние по умолчанию возвращено).
    await (await radio('יחיד')).click();
    await expectSelected('יחיד', 'מניין');

    if (!hasDeepLinks()) await switchNusach('אשכנזי');
  });
});
